const STATS = (() => {
  const ids = new Set(SUBMISSIONS.map(s => s.cityId));
  const sc = CITIES.filter(c => ids.has(c.id));
  return {
    submissions: SUBMISSIONS.length,
    cities: sc.length,
    countries: new Set(sc.map(c => c.country)).size,
    continents: new Set(sc.map(c => c.continent)).size,
    photos: SUBMISSIONS.reduce((n,s) => n + s.photos.length, 0),
    contributors: Object.keys(CONTRIBUTORS).length,
    comments: SUBMISSIONS.reduce((n,s) => n + s.comments.length, 0),
  };
})();

if (typeof window !== "undefined") Object.assign(window, { CONTRIBUTORS, CITIES, SUBMISSIONS, STATS });
